import{_ as l,a0 as p,w as o,s as n,ao as u,I as s,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"樹莓派 4 來襲！ | LCTT x X-CMD","titleTemplate":false,"description":"樹莓派 4 來襲！ | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"樹莓派 4 來襲！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"樹莓派 4 來襲！ | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190624 Raspberry Pi 4 is here","title":"樹莓派 4 來襲！","tag":"201906","desc":""},"relativePath":"201906/20190624 Raspberry Pi 4 is here.md","filePath":"[post].md"}'),b={name:"201906/20190624 Raspberry Pi 4 is here.md"};function d(m,e,f,B,h,P){const i=p("Link");return o(),n("div",null,[e[15]||(e[15]=u('<h1 id="樹莓派-4-來襲" tabindex="-1">樹莓派 4 來襲！ <a class="header-anchor" href="#樹莓派-4-來襲" aria-label="Permalink to “樹莓派 4 來襲！”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/29/161918icu6zrn8qrg3p38u.png" alt=""></p><blockquote><p>售價 35 美元起的新一代樹莓派單板計算機，裝載了 1.5 GHz 的 Arm 芯片，並支持雙 HDMI 4K 顯示，全吞吐量千兆以太網，以及更多新特性。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/raspberry-pi-4_lead.jpg?itok=2bkk43om" alt="Raspberry Pi 4 board" title="Raspberry Pi 4 board"></p><p>樹莓派的最新版本樹莓派 4 代，已於近日（北京時間 6 月 24 日）發佈，這早於此前預期。樹莓派 4 裝載了 1.5 GHz 的 Arm 芯片和 VideoCore GPU，支持雙 4K 顯示輸出，並引入了 USB 3 接口和全吞吐量千兆以太網，以及最高可達 4G 的多個可選 RAM 配置。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspberry-pi-4-case.jpg" alt="Raspberry Pi 4 case" title="Raspberry Pi 4 case"></p><p>樹莓派 4 是非常強大的單板計算機，其起始售價依然是 35 美元。起始版的 RAM 配置為 1G，2G RAM 配置的樹莓派售價為 45 美元，頂配 4G RAM 的樹莓派售價為 55 美元，採用這種差異化定價對樹莓派尚屬首次。</p><p>樹莓派 4 的詳細配置如下：</p><ul><li>1.5 GHz 4 核心 64 位博通 BCM2711 A72 CPU</li><li>VideoCore VI GPU</li><li>千兆以太網端口</li><li>1GB/2GB/4GB LPDDR4 SDRAM 內存</li><li>雙 Micro-HDMI 接口</li><li>兩個 USB 3 接口</li><li>兩個 USB 2 接口</li><li>雙頻（2.4 GHz 和 5 GHz）無線網絡</li><li>藍牙 5.0</li><li>USB Type C 電源接口</li><li>CSI 攝像頭接口</li><li>DSI 顯示接口</li><li>MicroSD 卡槽</li><li>PoE（以太網供電）供電針</li><li>完全兼容早期的樹莓派產品</li></ul><h3 id="usb-接口和網絡" tabindex="-1">USB 接口和網絡 <a class="header-anchor" href="#usb-接口和網絡" aria-label="Permalink to “USB 接口和網絡”">​</a></h3><p>樹莓派 4 板載了更高速率的 USB 3 接口；它通過 Type C 接口供電，並提供兩個 USB 3 接口和兩個 USB 2 接口。USB 3 接口可以為連接的硬盤和其它外部設備提供更高的速率。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspberry-pi-4-usb.jpg" alt="Raspberry Pi 4 USBs" title="Raspberry Pi 4 USBs"></p><p>基於 BCM2835 的樹莓派 1 到 3 代的芯片只有一個本地 USB 接口，並且沒有以太網接口，因而需要使用板子的 USB 集線器給出更多的 USB 接口和以太網接口。樹莓派 3B+ 增加了一個專用的局域網（LAN）芯片，裝載了千兆以太網，但它受到 USB 2 速率的限制。樹莓派 4 板載了專門的千兆以太網，並且由於它不再受到 USB 速率的限制，網絡速度要快得多。</p><p>樹莓派 4 採用了 3B+ 中已有的技術 —— 該技術使得樹莓派 3B+ 成為了第一個帶有雙頻無線網絡的單板計算機，即可以同時連接 2.4 GHz 和 5 GHz 頻率的網絡。</p><h3 id="顯示" tabindex="-1">顯示 <a class="header-anchor" href="#顯示" aria-label="Permalink to “顯示”">​</a></h3><p>設計第一代樹莓派時，其 CPU 和 GPU 性能的平衡大大偏向於 GPU。VideoCore IV 是一個非常強大的圖形處理器，支持全高清 1080p 多媒體的處理，這就是為什麼樹莓派一直作為家庭媒體中心而廣受歡迎的原因。樹莓派 2 代在某種程度上進行了權衡修改，並將 CPU 的性能進行提升，將樹莓派從單核發展成四核 ARM 芯片。而樹莓派 4 代將 CPU 和 GPU 的性能都進行了大幅提升。新的 VideoCore VI GPU 支持 4K 視頻，並允許通過板子上的兩個 Micro HDMI 端口（板子特意保持了和舊有型號相同的尺寸）進行雙顯示輸出，這裏要用一個適配器或 Micro HDMI 轉 full HDMI 的轉換線連接到 HDMI 屏幕。</p><p>當你需要同時瀏覽多個窗口時，需要用到更多的物理顯示屏，雙顯示的好處在此時就得到了絕佳體現。如果你正在編程，你可能會在其中一個屏幕上編寫代碼，構建網站或應用，而在另一個屏幕上查看資料庫、Web 瀏覽器、電子郵件或其他內容。這是樹莓派首次可以不必將開發局限在一台顯示器上，從而可以讓你在需要時，在不同的屏幕上構建具有不同內容的基於樹莓派的項目。</p><p>該樹莓派還有一個顯示器串行接口（DSI)，用於驅動另一個特殊的顯示-這裏並非指另一個監視器本身，而是通過一根撓性電纜連接的官方樹莓派觸摸屏顯示器。</p><h3 id="raspbian-buster" tabindex="-1">Raspbian Buster <a class="header-anchor" href="#raspbian-buster" aria-label="Permalink to “Raspbian Buster”">​</a></h3><p>樹莓派 4 發佈後，緊接着更新了基於 Debian 的系統 Raspbian Buster，而新的樹莓派對 OpenGL ES 3 的支持，使我們在 Raspbian Buster 上為樹莓派 4 開發任意軟件成為可能。Buster 對界面進行了一些調整，並對很多軟件進行了升級，其中包括 Python3.7。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspbian-buster.png" alt="Raspbian Buster" title="Raspbian Buster"></p><h3 id="開源圖形驅動程序" tabindex="-1">開源圖形驅動程序 <a class="header-anchor" href="#開源圖形驅動程序" aria-label="Permalink to “開源圖形驅動程序”">​</a></h3><p>在過去的五年中，Eric Anholt 一直致力於為樹莓派編寫開源圖形驅動程序。現在，Raspbian 可以使用這個驅動程序加速樹莓派上的 Web 瀏覽、桌面圖形和 3D 應用，這取代了以前需要的大量閉源代碼。非常感謝 Eric 和博通的貢獻。</p><p>按之前預計，樹莓派 4 將於明年完成，但由於芯片設計比預期更早投入生產，樹莓派 4 因而可以提早到現在發佈。</p><hr><p>樹莓派 4 已經開始發售，你會選擇哪個型號呢？在評論中説出你的想法吧。</p><hr>',27)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(i,{href:"https://opensource.com/article/19/6/raspberry-pi-4"},{default:a(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/19/6/raspberry-pi-4",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=t("作者：",-1)),r(i,{href:"https://opensource.com/users/bennuttall"},{default:a(()=>[...e[2]||(e[2]=[t("Ben Nuttall",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),r(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(i,{href:"https://github.com/wahailin"},{default:a(()=>[...e[4]||(e[4]=[t("wahailin",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),r(i,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const R=l(b,[["render",d]]);export{U as __pageData,R as default};
